      company: job.company || '',
      job_url: job.url || `https://remoteok.com/jobs/${job.id || ''}`,
      source: 'RemoteOK',
      location_text: job.location || 'worldwide',
      salary: job.salary || '',
      description: (job.description || '') + ' Tags: ' + (Array.isArray(job.tags) ? job.tags.join(', ') : ''),
      posted_date: job.date || new Date().toISOString(),
      tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
      date_found: new Date().toISOString().split('T')[0],
      _record_type: 'new'
    }
  }));

