const items = $input.all();
if (!items || items.length === 0) return [];

const data = items[0].json;
const jobs = data.jobs || (Array.isArray(data) ? data : []);

return jobs
  .filter(job => job && (job.title || job.role))
  .map(job => ({
    json: {
      job_title: job.title || job.role || '',
      company: (job.company && job.company.name) || job.company || '',
      job_url: job.applicationUrl || `https://himalayas.app/jobs/${job.slug || job.id || ''}`,
      source: 'Himalayas',
