      description: job.description || '',
      posted_date: job.publishedAt || job.createdAt || new Date().toISOString(),
      tags: Array.isArray(job.skills) ? job.skills.join(', ') : '',
      date_found: new Date().toISOString().split('T')[0],
      _record_type: 'new'
