const items = $input.all();
return items.map(item => {
  const rss = item.json;
  const title = rss.title || '';
  // Dynamite format: "Job Title - Company Name"
  const dashIdx = title.lastIndexOf(' - ');
  const jobTitle = dashIdx > -1 ? title.substring(0, dashIdx).trim() : title;
  const company = dashIdx > -1 ? title.substring(dashIdx + 3).trim() : '';

  return {
    json: {
      job_title: jobTitle,
      company: company,
      job_url: rss.link || rss.guid || '',
      source: 'Dynamite Jobs',
      location_text: 'worldwide',
      salary: '',
      description: rss.content || rss['content:encoded'] || rss.summary || rss.description || '',
      posted_date: rss.pubDate || rss.isoDate || new Date().toISOString(),
      tags: '',
      date_found: new Date().toISOString().split('T')[0],
      _record_type: 'new'
    }
  };
});

const items = $input.all();
if (!items || items.length === 0) return [];

const data = items[0].json;
const jobs = Array.isArray(data) ? data : (data.jobs || data.results || []);

return jobs
  .filter(job => job && (job.title || job.role))
  .map(job => ({
    json: {
      job_title: job.title || job.role || '',
      company: job.company_name || (job.company && job.company.name) || job.company || '',
      job_url: job.url || job.absolute_url || `https://www.workatastartup.com/jobs/${job.id || ''}`,
      source: 'YC Work at a Startup',
      location_text: job.location || (job.remote ? 'worldwide' : ''),
      salary: job.salary_min ? `$${job.salary_min}-${job.salary_max || '?'}/yr` : (job.compensation || ''),
      description: job.description || job.body || '',
      posted_date: job.created_at || job.posted_at || new Date().toISOString(),
      tags: Array.isArray(job.skills) ? job.skills.join(', ') : '',
      date_found: new Date().toISOString().split('T')[0],
      _record_type: 'new'
    }
  }));

const allInputs = $input.all();
const existingUrls = new Set();
const existingKeys = new Set();
const newJobs = [];

// Separate existing records from new job candidates
for (const item of allInputs) {
  if (item.json._record_type === 'existing') {
    const url = (item.json.job_url || '').trim().toLowerCase();
    const key = `${(item.json.company || '').toLowerCase()}|${(item.json.job_title || '').toLowerCase()}`;
    if (url) existingUrls.add(url);
    if (key !== '|') existingKeys.add(key);
  } else {
    newJobs.push(item);
  }
}

// Deduplicate new jobs against existing and each other
const result = [];
const seenUrls = new Set(existingUrls);
const seenKeys = new Set(existingKeys);

for (const item of newJobs) {
  const url = (item.json.job_url || '').trim().toLowerCase();
  const key = `${(item.json.company || '').toLowerCase()}|${(item.json.job_title || '').toLowerCase()}`;

  if (!item.json.job_title && !url) continue;
  if (url && seenUrls.has(url)) continue;
  if (!url && key !== '|' && seenKeys.has(key)) continue;

  if (url) seenUrls.add(url);
  if (key !== '|') seenKeys.add(key);

  const { _record_type, ...cleanJob } = item.json;
  result.push({ json: cleanJob });
}

if (result.length === 0) {
  // Return a sentinel so downstream nodes don't error on empty
  return [{ json: { _skip: true, _message: 'No new jobs found today', date_found: new Date().toISOString().split('T')[0] } }];
}

return result;

const item = $input.item;
if (item.json._skip) return { json: { ...item.json, passes_hard_filter: false, hard_filter_reason: 'Skipped — no new jobs' } };

const text = (
  (item.json.description || '') + ' ' +
  (item.json.location_text || '') + ' ' +
  (item.json.job_title || '') + ' ' +
  (item.json.title || '')
).toLowerCase();

const rejectPatterns = [
  'us only', 'usa only', 'united states only', 'us residents only',
  'canada only', 'uk only', 'eu only', 'europe only', 'australia only',
  'must be based in', 'must live in', 'must reside in',
  'must be authorized to work in', 'authorized to work in the us',
  'authorized to work in the united states', 'employment authorization',
  'local work permit required', 'work permit required',
  'must be onsite', 'on-site required', 'onsite required', 'office required',
  'in-office', 'hybrid role', 'hybrid position',
  'remote within us', 'remote within usa', 'us remote only',
  'remote us only', 'domestic us', 'remote in the us', 'remote in us',
  'fixed us hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours',
  'must overlap full us', 'no international', 'domestic only',
  'must be located in', 'must be a us citizen', 'must be a uk citizen',
  'work visa sponsorship not available for this role',
  'we are unable to sponsor'
];

for (const pattern of rejectPatterns) {
  if (text.includes(pattern)) {
    return {
      json: {
        ...item.json,
        passes_hard_filter: false,
        hard_filter_reason: `Rejected by hard filter: "${pattern}"`
      }
    };
  }
}

const positiveSignals = [
  'worldwide', 'work from anywhere', 'global remote', 'anywhere in the world',
  'apac', 'international contractor', 'deel', 'remote.com', 'oyster',
  'remote first', 'remote-first', 'distributed team', 'fully distributed',
  'asynchronous', 'eor', 'employer of record', 'b2b contractor',
  'open to international', 'global team', 'timezone flexible'
];

const found = positiveSignals.filter(p => text.includes(p));

return {
  json: {
    ...item.json,
    passes_hard_filter: true,
    hard_filter_reason: 'Passed hard filter',
    positive_signals: found.join(', ')
  }
};

const item = $input.item;
const job = item.json;

const prompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."
Reject the job if it requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan.
Reject the job if it requires local work authorization outside Taiwan.
Reject the job if it is hybrid, onsite, or remote within one country only.
Reject the job if it requires fixed working hours that would force Jerry to work through the night in Taiwan (e.g. fixed EST/PST/CET overlap).

Keep the job only if one of these is true:
- The job says worldwide remote.
- The job says work from anywhere.
- The job says global remote.
- The job says APAC remote.
- The job allows international contractors.
- The job accepts people based anywhere.
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement.

Return JSON only — no other text:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "short reason (max 30 words)",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job Title: ${job.job_title}
Company: ${job.company}
Location Text: ${job.location_text}
Salary: ${job.salary}

Job Post (first 3000 chars):
${(job.description || '').substring(0, 3000)}`;

return {
  json: {
    ...job,
    _api_body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 400,
      messages: [{ role: 'user', content: prompt }]
    })
  }
};

const apiResponse = $input.item.json;
const jobData = $('Prepare AI Request').item.json;

// Parse Claude response
let aiResult = {};
try {
  const textContent = (apiResponse && apiResponse.content && apiResponse.content[0] && apiResponse.content[0].text) || '';
  const jsonMatch = textContent.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    aiResult = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'AI parse error',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };
}

// Async level check
const text = (jobData.description || '').toLowerCase();

const asyncKeywords = [
  'asynchronous', 'async', 'async-first', 'async first',
  'flexible hours', 'flexible schedule', 'work your own hours',
  'no fixed hours', 'low meeting', 'meeting-light', 'no meetings',
  'distributed team', 'remote first', 'remote-first',
  'work across time zones', 'overlap not required', 'self-directed',
  'own schedule', 'results-oriented', 'results driven'
];
const syncKeywords = [
  'strict 9 to 5', 'fixed us hours', 'fixed est', 'fixed pst', 'fixed cet',
  'daily standups required', 'daily live calls required', 'must be online',
  'must overlap full business day', 'core hours required',
  'must be available 9am', 'must work est', 'must work pst'
];

const asyncFound = asyncKeywords.filter(k => text.includes(k));
const syncFound = syncKeywords.filter(k => text.includes(k));

let asyncLevel;
if (syncFound.length > 0) {
  asyncLevel = 'low';
} else if (asyncFound.length >= 3) {
  asyncLevel = 'high';
} else if (asyncFound.length >= 1) {
  asyncLevel = 'medium';
} else {
  asyncLevel = 'unknown';
}

// Role fit
const roleMap = {
  'data analyst': ['data analyst', 'data analysis'],
  'data scientist': ['data scientist', 'data science', 'machine learning', 'ml engineer'],
  'bi analyst': ['bi analyst', 'business intelligence', 'power bi', 'tableau analyst'],
  'marketing analyst': ['marketing analyst', 'marketing analytics', 'performance marketing analyst'],
  'growth analyst': ['growth analyst', 'growth hacking', 'growth marketing'],
  'ai specialist': ['ai specialist', 'ai automation', 'ai workflow', 'prompt engineer', 'llm', 'generative ai', 'ai marketing'],
  'automation': ['automation specialist', 'workflow automation', 'rpa', 'no-code', 'martech ops'],
  'martech': ['martech', 'marketing technology', 'marketing operations', 'marketing ops'],
  'creative strategist': ['creative strategist', 'content strategist'],
  'data engineer': ['analytics engineer', 'data engineer', 'etl']
};
const adjacentRoles = ['developer', 'engineer', 'designer', 'copywriter', 'writer', 'manager', 'strategist'];

const titleAndDesc = ((jobData.job_title || '') + ' ' + text);
let roleCategory = 'other';
let roleFitScore = 0;

for (const [cat, keywords] of Object.entries(roleMap)) {
  if (keywords.some(k => titleAndDesc.includes(k))) {
    roleCategory = cat;
    roleFitScore = 25;
    break;
  }
}
if (roleFitScore === 0 && adjacentRoles.some(r => titleAndDesc.includes(r))) {
  roleFitScore = 15;
  roleCategory = 'adjacent';
}

// Scoring (max 100)
let score = 0;

// Taiwan eligibility (40 pts max)
const eligible = aiResult.taiwan_eligible || 'unclear';
const locRisk = aiResult.location_risk || 'medium';
if (eligible === 'yes' && locRisk === 'low') score += 40;
else if (eligible === 'yes' || locRisk === 'low') score += 30;
else if (eligible === 'unclear' && locRisk === 'medium') score += 20;
else if (eligible === 'unclear') score += 10;
else score += 0;

// Also award points for positive signals found during hard filter
if ((jobData.positive_signals || '').length > 0) score = Math.max(score, 20);

// Async fit (25 pts max)
if (asyncLevel === 'high') score += 25;
else if (asyncLevel === 'medium') score += 20;
else if (asyncLevel === 'unknown') score += 10;
else score += 0;

// Role fit (25 pts max)
score += roleFitScore;

// Salary fit (10 pts base, up to 25 pts)
const salaryText = (jobData.salary || '').toLowerCase().replace(/,/g, '');
if (salaryText) {
  const nums = salaryText.match(/(\d+)/g);
  if (nums && nums.length > 0) {
    const amounts = nums.map(n => parseInt(n));
    const maxAmt = Math.max(...amounts);
    const monthly = maxAmt > 20000 ? maxAmt / 12 : maxAmt;
    if (monthly >= 5000) score += 25;
    else if (monthly >= 3000) score += 15;
    else score += 10;
  } else {
    score += 10;
  }
}

// Why it fits
const whyFit = [];
if (eligible === 'yes') whyFit.push('Taiwan eligible');
if (asyncLevel === 'high') whyFit.push('Fully async');
else if (asyncLevel === 'medium') whyFit.push('Async-friendly');
if (roleFitScore >= 25) whyFit.push(`Strong role match: ${roleCategory}`);
if (score >= 85) whyFit.push('Top-tier overall match');
if (aiResult.contractor_possible === 'yes') whyFit.push('Contractor arrangement possible');

return {
  json: {
    ...jobData,
    taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
    taiwan_reason: aiResult.reason || '',
    location_risk: aiResult.location_risk || 'medium',
    timezone_risk: aiResult.timezone_risk || 'medium',
    contractor_possible: aiResult.contractor_possible || 'unclear',
    ai_decision: aiResult.decision || 'manual_check',
    async_level: asyncLevel,
    role_category: roleCategory,
    score: Math.min(score, 100),
    why_good_fit: whyFit.join('; '),
    application_status: 'new',
    notes: '',
    _api_body: undefined
  }
};

const item = $input.item;
const job = item.json;

const prompt = `Write a short cover letter for Jerry.

Jerry is based in Taiwan and wants async global remote work.

Jerry's background:
- Bilingual English and Mandarin (grew up in California and Taiwan)
- Digital marketing background
- Data science bootcamp graduate
- Technical skills: Python, SQL, Tableau, Power BI
- Marketing skills: Performance marketing, SEO, PPC, GA4, Meta Ads, Google Ads
- AI tools: ChatGPT, Claude, Gemini, Cursor
- Project experience: dashboards, EDA, machine learning projects, customer segmentation, fraud detection, marketing analytics

Job he is applying for:
Title: ${job.job_title}
Company: ${job.company}
Role Category: ${job.role_category}
Why it fits: ${job.why_good_fit}

Job description (first 1500 chars):
${(job.description || '').substring(0, 1500)}

Write a cover letter that:
- Is specific to this job and company
- Mentions how Jerry can help the company: reduce manual analysis time, improve reporting speed, connect marketing and data, build AI-assisted workflows, turn messy data into business action
- Is under 220 words
- Tone: confident, direct, human, not desperate
- Do NOT use generic openers like "I am writing to express my interest"
- Start with a compelling first sentence that hooks the reader`;

return {
  json: {
    ...job,
    _cover_api_body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 600,
      messages: [{ role: 'user', content: prompt }]
    })
  }
};

const apiResponse = $input.item.json;
const jobData = $('Prepare Cover Letter Request').item.json;

let coverLetter = '';
try {
  coverLetter = (apiResponse && apiResponse.content && apiResponse.content[0] && apiResponse.content[0].text) || 'Cover letter generation failed';
} catch(e) {
  coverLetter = 'Cover letter generation failed';
}

return {
  json: {
    ...jobData,
    cover_letter_draft: coverLetter,
    _cover_api_body: undefined
  }
};

const allData = $input.all();
if (!allData || allData.length === 0) {
  return [{ json: {
    subject: 'Taiwan Jobs: No qualifying jobs today',
    html_body: '<p>No qualifying jobs found today (score 70+).</p>'
  }}];
}

const jobs = (allData[0].json.all_jobs || []).filter(j => !j._skip);

if (jobs.length === 0) {
  return [{ json: {
    subject: 'Taiwan Jobs: No qualifying jobs today',
    html_body: '<p>No qualifying jobs found today (score 70+). All jobs were filtered out.</p>'
  }}];
}

// Sort by score descending
jobs.sort((a, b) => (b.score || 0) - (a.score || 0));

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Taipei'
});

const topScore = jobs[0]?.score || 0;
const instantAlerts = jobs.filter(j => j.score >= 85);
const manualChecks = jobs.filter(j => j.ai_decision === 'manual_check');

let html = `
<div style="font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto;">
<h2 style="color:#1a1a2e;">Daily Taiwan Eligible Async Remote Jobs</h2>
<p><strong>${today}</strong></p>
<p>Found <strong>${jobs.length}</strong> qualifying jobs (score 70+). Top score: <strong>${topScore}/100</strong></p>
`;

if (instantAlerts.length > 0) {
  html += `<div style="background:#fff3cd;border:1px solid #ffc107;padding:12px;border-radius:6px;margin:12px 0;">
<strong>⭐ ${instantAlerts.length} HIGH-PRIORITY JOB${instantAlerts.length > 1 ? 'S' : ''} (85+) — Apply today</strong></div>`;
}

html += '<hr style="margin:20px 0;">';

// List all jobs
jobs.forEach((job, idx) => {
  const isHot = job.score >= 85;
  const border = isHot ? '#28a745' : '#dee2e6';
  const bg = isHot ? '#f8fff9' : '#ffffff';
  const badge = isHot ? ' <span style="background:#28a745;color:#fff;padding:2px 8px;border-radius:10px;font-size:12px;">APPLY NOW</span>' : '';

  html += `
<div style="border:1px solid ${border};background:${bg};padding:16px;margin:12px 0;border-radius:6px;">
  <h3 style="margin:0 0 8px 0;">${idx + 1}. ${job.job_title || 'Unknown Title'}${badge}</h3>
  <table style="width:100%;font-size:14px;border-collapse:collapse;">
    <tr><td style="padding:3px 8px 3px 0;color:#666;width:160px;"><strong>Company</strong></td><td>${job.company || '—'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Score</strong></td><td>${job.score}/100</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Taiwan Eligible</strong></td><td>${job.taiwan_eligible || '—'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Reason</strong></td><td>${job.taiwan_reason || job.hard_filter_reason || '—'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Async Level</strong></td><td>${job.async_level || '—'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Timezone Risk</strong></td><td>${job.timezone_risk || '—'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Salary</strong></td><td>${job.salary || 'Not listed'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Role Category</strong></td><td>${job.role_category || '—'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Why It Fits Jerry</strong></td><td>${job.why_good_fit || '—'}</td></tr>
    <tr><td style="padding:3px 8px 3px 0;color:#666;"><strong>Source</strong></td><td>${job.source || '—'}</td></tr>
  </table>
  <p style="margin:10px 0 0 0;"><a href="${job.job_url || '#'}" style="background:#0066cc;color:#fff;padding:8px 16px;border-radius:4px;text-decoration:none;font-size:14px;">Apply Here →</a></p>`;

  if (job.cover_letter_draft) {
    html += `
  <details style="margin-top:12px;">
    <summary style="cursor:pointer;font-weight:bold;color:#0066cc;">📝 Cover Letter Draft</summary>
    <div style="background:#f8f9fa;padding:12px;margin-top:8px;border-radius:4px;white-space:pre-wrap;font-size:13px;">${job.cover_letter_draft}</div>
  </details>`;
  }

  html += '\n</div>';
});

// Manual check section
if (manualChecks.length > 0) {
  html += `<hr style="margin:20px 0;"><h3>🔍 Manual Check (${manualChecks.length})</h3><p>These jobs scored well but Taiwan eligibility is unclear:</p><ul>`;
  manualChecks.forEach(j => {
    html += `<li><strong>${j.job_title}</strong> at ${j.company} — Score: ${j.score} — <a href="${j.job_url}">View</a></li>`;
  });
  html += '</ul>';
}

html += '<hr style="margin:20px 0;"><p style="font-size:12px;color:#999;">Generated by Taiwan Eligible Async Remote Job Hunter · Asia/Taipei</p></div>';

const subject = `Taiwan Jobs: ${jobs.length} found today | Top ${topScore}/100${instantAlerts.length > 0 ? ` | ⭐ ${instantAlerts.length} APPLY NOW` : ''}`;

return [{ json: { subject, html_body: html, jobs_count: jobs.length, top_score: topScore } }];
